/* Beginner strategy is editorial; availability, prices and access come from verified catalog IDs. */
(function(){'use strict';
const R=()=>window.RULES_DATA||{},ed=g=>String(g?.edition||'').toLowerCase(),E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),L=(en,ko,tag='span')=>`<${tag} data-i18n-en="${E(en)}" data-i18n-ko="${E(ko)}">${E(en)}</${tag}>`,N=r=>L(r.name,r.name_ko||window.UKI18n?.name(r.name)||r.name),P=(en,ko)=>window.MMRuleTerms?.prose(en,ko,{edition:'n26'})||L(en,ko,'p'),verified=r=>r.source_verified&&String(r.edition_slug||r.edition).toLowerCase()==='n26';
const profiles={
'House Cawdor':['Numbers, layered fire and a protected approach. Start with Pious before mixing paths.','인원수와 중첩 사격으로 접근로를 지키는 갱입니다. 입문자는 파이어스 한쪽으로 통일하면 관리가 쉽습니다.','Keep cheap fighters on objectives, support them with overlapping lanes and commit a short-range specialist only after its approach is covered.','저렴한 파이터가 목표를 맡고, 서로 겹치는 사선을 만드세요. 단거리 담당은 접근로를 확보한 뒤 투입합니다.'],
'House Escher':['Mobile fighters with distinct close-range and ranged roles.','기동성을 살리되 사격 담당과 근접 담당의 역할을 나누는 갱입니다.','Start with reliable basic guns and a small assault element. Use cover and flanks instead of paying for specialised chem combinations before learning activation order.','처음에는 기본 총기와 소수의 돌격 담당을 사용하세요. 복잡한 켐 조합에 먼저 투자하기보다 엄폐·측면 이동과 활성화 순서를 익히는 편이 쉽습니다.'],
'House Goliath':['Durable models, but a small roster can still lose objective coverage.','튼튼한 모델도 인원이 적으면 여러 목표를 동시에 지키기 어렵습니다.','Give the advance a ranged escort. Avoid buying an expensive melee weapon for every fighter before ensuring the team can reach combat.','전진조를 엄호할 사격 담당을 두세요. 모두에게 비싼 근접 무기를 사 주기 전에 실제 교전 거리까지 도달할 방법을 확보합니다.'],
'House Orlock':['A flexible combined-arms starting point.','기본 사격과 전진조를 함께 익히기 좋은 균형형 갱입니다.','Use basic weapons for dependable roles and concentrate expensive firepower on a few models. Leave reserve credits for campaign losses.','기본 무기로 역할을 명확히 하고 고가 화력은 소수에게 집중하세요. 캠페인 손실에 대비한 예비 크레딧도 남겨 둡니다.'],
'House Van Saar':['A ranged core that must still move to score.','사격 기반을 갖추되 득점을 위한 이동조가 필요한 갱입니다.','Pair firing lanes with cheap objective runners. Do not let the entire roster stand still while the opponent controls the mission.','사격조와 저렴한 목표 이동조를 나누세요. 전원이 제자리에 서 있으면 상대가 임무를 수행하는 동안 득점 기회를 놓칠 수 있습니다.'],
'House Delaque':['Positioning and information matter more than an unsupported lone specialist.','위치 선정과 협력이 중요하며, 고립된 특수 모델만 믿는 운영은 어렵습니다.','Begin with a clear ranged core and cheap movers. Add Wyrd powers and specialist tricks one at a time, checking their subtype and access requirements.','사격 핵심과 저렴한 이동조부터 정하세요. 워드 파워와 특수 운용은 서브타입·접근 조건을 확인하며 하나씩 추가합니다.'],
'Palanite Enforcers':['Start with a clear patrol role for each model.','모델마다 순찰조 안의 역할을 먼저 정하세요.','Check patrol-specific recruitment and equipment rules before using a House example. Support short-range control with overlapping fire and avoid isolated advances.','하우스 예시를 그대로 복사하기 전에 순찰대의 모집·장비 규칙을 확인하세요. 단거리 통제 담당을 중첩 사격으로 지원하고 단독 전진은 피합니다.'],
'Venator Gangs':['Keep the first custom hunter team simple.','첫 현상금 사냥꾼 팀은 선택지를 단순하게 유지하는 편이 좋습니다.','Set one role per hunter, then resolve the chosen legacy and its equipment access. A weapon shown in another gang guide is not automatically available to this team.','헌터마다 역할 하나를 정한 다음 선택한 레거시와 장비 접근을 확인하세요. 다른 갱 가이드에 보이는 무기가 이 팀에도 자동 허용되는 것은 아닙니다.'],
'Corpse Grinder Cults':['The approach is part of the melee plan.','근접전에 도달하는 과정부터 전술로 계획해야 합니다.','Use terrain to limit incoming fire, threaten more than one approach and avoid advancing the most valuable model alone. Check each model’s actual weapon restrictions.','지형으로 적 사격을 줄이고 둘 이상의 접근로를 위협하세요. 가장 비싼 모델을 혼자 보내지 말고, 각 모델의 실제 무기 제한을 확인합니다.'],
'Outcasts':['Choose an identity before purchasing a collection of unrelated specialists.','서로 다른 특수 모델을 모으기 전에 갱의 중심 역할부터 정하세요.','Resolve the leader’s affiliation, archetype and special recruitment rules first. Add affordable support around that choice and recheck skill access after configuration.','리더의 소속·아키타입과 특수 모집 조건부터 정하세요. 그 선택을 지원하는 저렴한 인원을 추가하고 설정 후 스킬 접근을 다시 확인합니다.'],
'Free Ogryns':['Protect the route to close combat.','근접전까지 도달할 이동 경로를 지키는 것이 중요합니다.','Check Ogryn-specific equipment and fixed grants. Plan how slower or short-ranged models cross open areas rather than importing a standard gunline shopping list.','오그린 전용 장비와 고정 지급 항목을 확인하세요. 일반 사격 갱의 구매 목록을 복사하기보다 느리거나 사거리가 짧은 모델이 개활지를 건널 방법을 계획합니다.'],
'Genestealer Cults':['Build around an affordable core before adding complex psychic support.','저렴한 핵심 인원을 갖춘 뒤 복잡한 사이킥 지원을 추가하세요.','Keep leader, ordinary workers and support roles distinct. Wyrd powers require their actual model and subtype conditions; a cult theme alone does not grant every power.','리더·일반 인원·지원 담당을 구분하세요. 워드 파워는 실제 모델·서브타입 조건이 필요하며, 컬트라는 테마만으로 모든 파워가 허용되지는 않습니다.'],
'Chaos Helots':['A reliable core makes special rules easier to learn.','안정적인 기본 인원을 갖추면 특수 규칙도 익히기 쉽습니다.','Keep income, special abilities and ordinary combat roles separate. Resolve the actual leader and Witch rules instead of assuming every cultist is a Wyrd.','수입·특수 능력·일반 전투 역할을 구분하세요. 모든 컬티스트를 워드로 간주하지 말고 리더와 위치의 실제 규칙을 확인합니다.'],
'The Malstrain':['Treat unusual models and territory needs as a specific roster plan.','특이한 모델과 영역 운용을 별도의 명단 계획으로 다루세요.','Read each model’s fixed skills, movement and equipment entry. Check the gang’s own composition rules before applying ordinary House ratios or recruitment assumptions.','각 모델의 고정 스킬·이동·장비 항목을 읽으세요. 일반 하우스의 인원 비율이나 모집 방식을 적용하기 전에 이 갱의 별도 구성 규칙을 확인합니다.'],
'Spyre Hunters':['Each hunter is a large share of the team.','각 헌터가 팀에서 차지하는 비중이 큽니다.','Plan complementary hunting roles and read the suit-specific recruitment and improvement rules. The ordinary eight-model House example is not a Spyre list.','서로 보완하는 사냥 역할을 정하고 슈트별 모집·개량 규칙을 읽으세요. 일반 하우스 8명 예시는 스파이어 명단이 아닙니다.'],
'Ironhead Squats':['Reliable fire needs a plan for objective movement.','안정적인 화력에도 목표를 향한 이동 계획이 필요합니다.','Cover the advance with a firing base and avoid spending the entire budget on one gun. Check Squat-specific weapons and movement limits before assigning roles.','사격 거점으로 전진조를 지원하고 한 자루에 예산을 모두 쓰지 마세요. 역할을 정하기 전에 스쿼트 전용 무기와 이동상의 한계를 확인합니다.'],
'Ash Waste Nomads':['Match the roster to the battlefield and campaign.','전장과 캠페인 환경에 맞춰 명단을 구성하세요.','Read Nomad-specific recruitment, equipment and environmental rules. Keep objective movers and ranged support distinct; do not assume the normal Trading Post list applies unchanged.','노매드 전용 모집·장비·환경 규칙을 확인하세요. 목표 이동조와 사격 지원을 구분하고 일반 거래소 목록이 그대로 적용된다고 가정하지 않습니다.']
};
const houseNames={
'House Escher':['Escher Gang Queen','Escher Gang Matriarch','Escher Gang Sister','Escher Little Sister'],
'House Goliath':['Goliath Forge Tyrant','Goliath Forge Boss','Goliath Bruiser','Goliath Bully'],
'House Orlock':['Orlock Road Captain','Orlock Road Sergeant','Orlock Gunner','Orlock Greenhorn'],
'House Van Saar':['Van Saar Prime','Van Saar Augmek','Van Saar Tek','Van Saar Subtek'],
'House Delaque':['Delaque Master of Shadow','Delaque Phantom','Delaque Ghost','Delaque Shadow']};
function typeOf(g){if(ed(g)!=='n26'||g.customGangTypeId)return null;const rows=(R().gangTypes||[]).filter(verified),key=g.gangTypeId||g.gang_type_id;const direct=rows.find(t=>t.id===key);if(direct)return direct;const named=rows.filter(t=>[t.name,t.name_ko,window.UKI18n?.name(t.name)].includes(g.faction));return named.length===1?named[0]:null;}
function equipment(t,g){const subtypes=t.fighter_subtypes||[],applicable=r=>!r.vehicle_type_id&&(!r.fighter_type_id||r.fighter_type_id===t.id)&&(!r.gang_type_id||r.gang_type_id===t.gang_type_id)&&(!r.gang_origin_id||r.gang_origin_id===g.originId)&&(!r.gang_affiliation_id||r.gang_affiliation_id===g.affiliationId)&&(!r.gang_subtype_id||[...(g.subtypeIds||[]),g.subtypeId].includes(r.gang_subtype_id))&&(!r.fighter_subtype||subtypes.includes(r.fighter_subtype))&&(!r.required_specialisation_names?.length||r.required_specialisation_names.includes('Gunner'));
 const access=(R().fighterEquipment||[]).filter(r=>verified(r)&&applicable(r)),ids=new Set(access.filter(r=>!r.excluded).map(r=>r.equipment_id));for(const r of access.filter(r=>r.excluded))ids.delete(r.equipment_id);
 return(R().equipment||[]).filter(e=>verified(e)&&ids.has(e.id)&&!e.profile_scope_unresolved).flatMap(e=>{const members=access.filter(r=>r.equipment_id===e.id&&!r.excluded),prices=(R().equipmentDiscounts||[]).filter(r=>verified(r)&&r.equipment_id===e.id&&applicable(r)),values=[...new Set(prices.filter(p=>p.adjusted_cost!=null&&Number.isFinite(Number(p.adjusted_cost))).map(p=>Number(p.adjusted_cost)))],cost=prices.length?(values.length===1?values[0]:null):e.cost,bearers=e.rule_data?.bearer_subtypes||e.rule_data?.carriers||[];if(cost==null||!Number.isFinite(Number(cost))||Number(cost)<0||members.some(r=>r.requires_weapon_names||r.target_weapon_name||r.replaces_equipment_name||r.purchase_timing)||bearers.length&&!bearers.some(x=>subtypes.includes(x)))return[];return[{...e,cost:Number(cost)}];});}
const preferences={leader:['Autogun','Lasgun','Boltgun','Stub cannon','Shotgun with solid & scatter ammo'],support:['Heavy stubber*','Plasma gun','Long rifle','Boltgun','Autogun','Lasgun','Stub cannon'],line:['Lasgun','Autogun','Stub cannon','Shotgun with solid & scatter ammo','Stub gun'],runner:['Stub gun','Laspistol','Autopistol','Fighting knife']};
function plan(g,path='pious'){const type=typeOf(g);if(!type)return{available:false,rows:[],type:null};let config;if(type.name==='House Cawdor')config=path==='fanatic'?[['Redemptionist Priest',1,'leader',['Shotgun with solid & scatter ammo','Fighting knife']],['Redemptionist Deacon',1,'support',['Shotgun with solid & scatter ammo','Fighting knife']],['Redemptionist Deacon',1,'support',['Autogun']],['Redemptionist Brethren',4,'line',['Autogun']],['Redemptionist Zealot',2,'runner',['Autopistol','Fighting knife']]]:[['Cawdor Word-Keeper',1,'leader',['Autogun','Fighting knife']],['Cawdor Firebrand',1,'support',['Heavy stubber*']],['Cawdor Firebrand',1,'line',['Cawdor polearm/blunderbuss with grape & purgation rounds*']],['Cawdor Brethren',3,'line',['Cawdor polearm/autogun*']],['Cawdor Brethren',2,'line',['Autogun']],['Cawdor Bonepicker',2,'runner',['Stub gun','Fighting knife']]];else if(houseNames[type.name]){const [a,b,c,d]=houseNames[type.name];config=[[a,1,'leader'],[b,2,'support'],[c,4,'line'],[d,1,'runner']];}else config=[];
 const errors=[],rows=config.map(([name,quantity,role,names])=>{const t=(R().fighterTypes||[]).find(t=>verified(t)&&t.gang_type_id===type.id&&t.name===name&&t.recruitment_ready);if(!t){errors.push(name);return null;}const list=equipment(t,g),gear=names?names.map(n=>list.find(e=>e.name===n)):[preferences[role].map(n=>list.find(e=>e.name===n)).find(Boolean)];if(gear.some(e=>!e))errors.push(name+' equipment');const items=gear.filter(Boolean),unitCost=Number(t.cost)+items.reduce((s,e)=>s+e.cost,0);if(t.cost==null||!Number.isFinite(unitCost))errors.push(name+' cost');return{type:t,quantity,role,equipment:items,unitCost,total:unitCost*quantity};}).filter(Boolean),total=rows.reduce((s,r)=>s+r.total,0);return{available:true,type,rows,errors,complete:rows.length>0&&!errors.length&&total<=1000,total,reserve:1000-total,count:rows.reduce((s,r)=>s+r.quantity,0),path};}
function ref(kind,row){return row?`<button type="button" class="gg-link" data-guide-kind="${E(kind)}" data-guide-id="${E(row.id)}">${N(row)}</button>`:'';}
function rule(id,en,ko){return`<button type="button" class="btn small" data-guide-kind="coreRules" data-guide-id="${E(id)}">${L(en,ko)}</button>`;}
const roleNames={leader:['Leader / support','리더·지원'],support:['Fire support','화력 지원'],line:['Core / advance','주력·전진'],runner:['Objective runner','목표 이동']};
function primary(t){const ids=new Set((R().fighterSkillAccess||[]).filter(a=>a.fighter_type_id===t.id&&a.access_level==='primary').map(a=>a.skill_type_id)),roles=['fighter',...(t.fighter_subtypes||[]).map(x=>x.toLowerCase())];return(R().skills||[]).filter(s=>verified(s)&&ids.has(s.skill_type_id)&&!(s.is_power||s.is_wyrd_power||s.rule_data?.is_power)&&(!s.rule_data?.eligible_models?.length||s.rule_data.eligible_models.some(v=>roles.includes(v.toLowerCase())))&&!(s.rule_data?.required_subtypes||[s.rule_data?.required_subtype||s.required_subtype].filter(Boolean)).some(v=>!roles.includes(v.toLowerCase())));}
function startSkills(t,role){const choices=primary(t),order=role==='leader'?['Iron Will','Mentor','Connected','Nerves of Steel']:role==='support'?['Nerves of Steel','Bulging Biceps','Fast Reload','Marksman','Fast Shot']:['Nerves of Steel','Dodge','Berserker','Combat Master','Clamber'];return order.map(n=>choices.find(s=>s.name===n)).filter(Boolean).concat(choices).filter((s,i,a)=>a.findIndex(v=>v.id===s.id)===i).slice(0,3);}
function roster(p){if(!p.rows.length)return P('This gang uses special recruitment or composition choices. Review its own rules and the role cards below before building a priced roster; an ordinary House example is not substituted.','이 갱은 특수 모집·구성 선택을 먼저 확인해야 합니다. 아래 유닛 역할과 갱 규칙을 확인한 뒤 예산을 정하세요. 일반 하우스 예시를 이 갱의 확정 명단처럼 표시하지 않습니다.');if(!p.complete)return P('A required catalogue price or access link is unavailable, so this example is not presented as a confirmed shopping list.','필요한 카탈로그 가격·접근 연결을 확인할 수 없어 확정 구매 목록으로 표시하지 않습니다.');return `<div class="gg-budget"><strong>${L('Example budget','예시 예산')} 1,000 cr</strong><span>${L('Models','인원')} ${p.count}</span><span>${L('Spend','구매 합계')} ${p.total} cr</span><span>${L('Reserve','예비금')} ${p.reserve} cr</span></div><div class="gg-grid">${p.rows.map(r=>`<article class="gg-card"><header><strong>${r.quantity} × ${ref('fighterTypes',r.type)}</strong><b>${r.total} cr</b></header><p>${L(...roleNames[r.role])} · ${r.type.cost} cr ${L('base','모집비')}</p><div class="gg-gear">${r.equipment.map(e=>`<span>${ref('equipment',e)} ${e.cost} cr</span>`).join('')}</div><p>${L('Each, including equipment','장비 포함 1명')} ${r.unitCost} cr</p>${(r.type.fighter_subtypes||[]).includes('Specialist')?P('Choose Gunner specialisation for this ranged example; its granted skill is separate from a Leader/Champion starting choice.','이 사격 중심 예시는 거너 전문화를 권장합니다. 전문화 지급 스킬은 리더·챔피언의 시작 선택과 별개입니다.'):''}</article>`).join('')}</div>`;}

function factionRules(g){
 const type=typeOf(g);if(!type)return {type:null,entries:[]};
 const entries=[],seen=new Set(),add=(r,kind)=>{if(!r.name||seen.has(r.name.toLowerCase()))return;seen.add(r.name.toLowerCase());entries.push({row:r,kind});};
 if(type.verified_fields?.includes('special_rules_details'))for(const row of type.special_rules_details||[])add(row,null);
 for(const row of R().effects||[])if(verified(row)&&row.effect_type==='Gang Rule'&&row.gang_type_id===type.id)add(row,'effects');
 return {type,entries};
}
function factionExplanation(detail){
 if(!detail)return '';
 const links=(detail.rules||[]).map(id=>(R().coreRules||[]).find(r=>r.id===id&&verified(r))).filter(Boolean);
 return `<div class="gg-rule-explanation"><details class="gg-rule-fold" data-guide-fold="explanation"><summary>${L('Explanation & conditions','설명·적용 조건')}</summary><div class="gg-rule-fold-content"><section class="gg-rule-when"><h5>${L('When it applies','언제 적용하나')}</h5>${P(...detail.when)}</section><section class="gg-rule-limit"><h5>${L('Common misunderstandings','헷갈리기 쉬운 점')}</h5>${P(...detail.limit)}</section>${links.length?`<nav class="gg-example-links" aria-label="Related rules" data-i18n-en-aria-label="Related rules" data-i18n-ko-aria-label="관련 판정 규칙">${L('Related rules','관련 판정 규칙','strong')}${links.map(r=>ref('coreRules',r)).join('')}</nav>`:''}</div></details><details class="gg-rule-fold" data-guide-fold="example"><summary>${L('Worked example','계산·상황 예시')}</summary><div class="gg-rule-fold-content"><section class="gg-rule-example">${P(...detail.example)}</section></div></details></div>`;
}

function factionDetail(type,row){
 const data=window.MMFactionRuleExamples;
 if(!data)return null;
 return data.rules[type.name]?.[row.name]||(row.name==='Starting Skills'&&row.rule_data?.primary_skills===1?data.starting:null);
}
function factionContent(g){
 const {type,entries}=factionRules(g);if(!type)return `<div class="gg-note">${L('Verified faction rules are available for N26 catalogue gangs. This roster needs its own edition or custom rules.','확인된 팩션 룰은 N26 카탈로그 갱에 제공합니다. 이 명단은 해당 판본 또는 사용자 정의 규칙을 확인하세요.')}</div>`;
 const badge=r=>r.rule_data?.path?L(r.rule_data.path,r.rule_data.path==='Path of the Pious'?'패스 오브 더 파이어스':'패스 오브 더 퍼내틱'):'';
 const notes=(type.name==='House Cawdor'?P('The two paths are alternatives chosen when founding the gang. Without Number adds an eligible Prospect from your roster to the crew; it does not recruit a free fighter.','두 길은 창설 때 고르는 서로 다른 선택지입니다. 위다웃 넘버는 명부에 있는 적격 프로스펙트를 크루에 추가하는 혜택이며 새 파이터를 무료로 모집하는 규칙이 아닙니다.'):type.name==='Venator Gangs'?P('Rank the four chosen Skill Sets at founding. Primary ranks are 1–2 for Leaders/Champions and 1 for Specialists; Secondary ranks are 3–4 for Leaders, 3 for Champions and 2–3 for Specialists. Claiming Bounties is one battle reward of 20 credits when its threshold is met.','창설 때 고른 스킬 세트 4개의 순위를 정합니다. 프라이머리는 리더·챔피언의 1~2위, 스페셜리스트의 1위입니다. 세컨더리는 리더의 3~4위, 챔피언의 3위, 스페셜리스트의 2~3위입니다. 클레이밍 바운티스는 조건 충족 시 전투 보상으로 20크레딧을 더하는 규칙입니다.'):'');
 const related=type.name==='Spyre Hunters'?[['fighterSubtypes',(R().fighterSubtypes||[]).find(r=>verified(r)&&r.name==='Spyrer')],['territories',(R().territories||[]).find(r=>verified(r)&&r.name==='Spyrer Base Camp')]]:[];
 return `<div class="gg-faction" data-faction-id="${E(type.id)}"><div class="gg-rule-summary"><span class="gg-eyebrow">${L('N26 · Faction rules','N26 · 팩션 룰')}</span><h3>${N(type)}</h3>${P(type.description_en||'',type.description||type.description_en||'')}</div>${window.MMFactionRuleExamples?.summaries[type.name]?`<aside class="gg-faction-extra"><h4>${L('Applying the gang entry','갱 항목 적용 예시')}</h4>${factionExplanation(window.MMFactionRuleExamples.summaries[type.name])}</aside>`:''}<div class="gg-rule-list">${entries.map(({row:r,kind},i)=>`<article class="gg-rule-card" data-faction-rule="${E(r.name)}"><header><span class="gg-rule-number">${String(i+1).padStart(2,'0')}</span><h4>${kind?ref(kind,r):N(r)}</h4></header>${badge(r)?`<div class="gg-rule-scope">${badge(r)}</div>`:''}${P(r.description_en||'',r.description||r.description_en||'')}${factionExplanation(factionDetail(type,r))}</article>`).join('')}</div>${notes?`<aside class="gg-note">${L('Before you apply it','적용 전에 확인할 점','strong')}${notes}</aside>`:''}<div class="gg-rules">${ref('gangTypes',type)}${related.filter(([,r])=>r).map(([k,r])=>ref(k,r)).join('')}${rule('n26-core-gang-composition','Common composition rules','공통 구성 규칙')}</div><p class="gg-caption">${L('Faction rules do not replace individual fighter, equipment or campaign conditions. Reading this page does not change the roster or apply rewards.','팩션 룰과 함께 파이터·장비·캠페인의 개별 조건도 확인하세요. 이 화면을 읽어도 명단 변경이나 보상 적용은 일어나지 않습니다.')}</p></div>`;
}
function reading(type){
 const entry=window.MMGangReading?.[type.name];if(!entry)return P('Read the faction profile and recruitment entries before choosing a play style.','플레이 스타일을 고르기 전에 팩션 프로필과 모집 항목을 확인하세요.');
 const card=(key,en,ko)=>`<article class="gg-card"><h3>${L(en,ko)}</h3>${P(...entry[key])}</article>`;
 return `<div class="gg-reading"><header class="gg-reading-head"><span class="gg-eyebrow">${L('Meet your gang','갱 알아보기')}</span><h3>${N(type)}</h3><p class="gg-tagline">${L(...entry.tagline)}</p></header><section class="gg-reading-story"><h4>${L('Life in the hive','하이브 속의 이들')}</h4>${entry.lore.map(pair=>P(...pair)).join('')}</section><div class="gg-grid">${card('strengths','What the gang does well','강점을 살리는 방법')}${card('weaknesses','Where the plan can struggle','약점과 주의할 상황')}</div><section class="gg-reading-story"><h4>${L('Try this in your first battle','첫 전투에서는 이렇게')}</h4>${P(...entry.opening)}</section><section class="gg-reading-story"><h4>${L('Common mistake & who it suits','흔한 실수와 잘 맞는 플레이어')}</h4>${P(...entry.mistake)}</section><aside class="gg-note">${L('Setting introduction and editorial advice. Numerical effects and restrictions are in Faction Rules; a thematic description does not grant an ability.','배경 소개와 추천 운용입니다. 수치 효과와 제한은 팩션 룰에서 확인하세요. 테마 설명 자체가 능력을 부여하지는 않습니다.')}<button type="button" class="btn small" data-guide-tab="faction">${L('Read faction rules →','팩션 룰 읽기 →')}</button></aside></div>`;
}
function openFaction(g=gang()){if(!g)return false;window.MMRuleReference.openContext('Faction Rules',`<div class="gg-guide">${factionContent(g)}</div>`,{nameKo:'갱 팩션 룰',activator:document.activeElement});document.querySelector('.mmrr-dialog')?.classList.add('gg-dialog');return true;}

const section=(id,body)=>`<section role="tabpanel" aria-labelledby="gg-tab-${id}" id="gg-panel-${id}" data-guide-panel="${id}" ${id==='about'?'':'hidden'}>${body}</section>`;
let context=null;
function content(g,path){const p=plan(g,path);if(!p.available)return `<div class="gg-note">${L('A verified N26 gang is required for catalogue-backed recommendations. Custom and other-edition rosters need their own campaign rulings.','카탈로그 기반 추천은 확인된 N26 갱에만 제공합니다. 사용자 갱·다른 판본에는 해당 캠페인의 규칙을 확인하세요.')}</div>`;const profile=profiles[p.type.name]||profiles.Outcasts,types=(R().fighterTypes||[]).filter(t=>verified(t)&&t.gang_type_id===p.type.id&&t.recruitment_ready),show=p.rows.length?p.rows.filter((r,i,a)=>a.findIndex(x=>x.type.id===r.type.id)===i):types.map(t=>({type:t,role:(t.fighter_subtypes||[]).includes('Leader')?'leader':(t.fighter_subtypes||[]).includes('Champion')?'support':'line'}));
 const tabs=[['about','Meet your gang','갱 알아보기'],['faction','Faction rules','팩션 룰'],['start','Recommended roster','추천 구성'],['gear','Weapons & roles','무장·역할'],['growth','Skills & growth','스킬·성장'],['play','How to play','운용 순서'],['check','Your roster','내 명단 점검']];
 const overview=`<div class="gg-note gg-intro">${L('N26 · Read-only guide. Roster examples use 1,000 credits; recommendations do not spend credits or grant abilities.','N26 · 읽기 전용 가이드입니다. 명단 예시는 1,000크레딧 기준이며, 추천을 읽어도 크레딧 지출이나 능력 부여는 일어나지 않습니다.')}</div>`;
 const paths=p.type.name==='House Cawdor'?`<div class="gg-paths">${L('Cawdor path example','코드로의 길 예시')} ${[['pious','Pious','파이어스'],['fanatic','Fanatic','퍼내틱']].map(([value,en,ko])=>`<button class="btn small" type="button" data-guide-path="${value}" aria-pressed="${path===value}">${L(en,ko)}</button>`).join('')}</div>${P('Pious and Fanatic examples are separate. Choose the matching path and Leader; these examples keep every model in the same subtype so the minority ratio is easy to track.','파이어스·퍼내틱 예시는 별도입니다. 선택한 길에 맞는 리더를 쓰며, 예시는 반대 서브타입 인원 비율을 관리하기 쉽도록 같은 계열로 통일했습니다.')}`:'';
 const unitCards=show.map(({type:t,role})=>{const gear=equipment(t,g),planned=p.rows.filter(r=>r.type.id===t.id).flatMap(r=>r.equipment),recommend=planned.concat((preferences[role]||preferences.line).map(n=>gear.find(e=>e.name===n)).filter(Boolean)).filter((e,i,a)=>a.findIndex(v=>v.id===e.id)===i).slice(0,5);return `<article class="gg-card"><h3>${ref('fighterTypes',t)} · ${L(...roleNames[role])}</h3><div class="gg-gear">${recommend.map(e=>`<span>${ref('equipment',e)} · ${e.cost} cr</span>`).join('')||L('Use this model’s own equipment entry.','이 모델의 전용 장비 항목을 확인하세요.')}</div>${role==='support'?P('Choose one main gun and an appropriate firing lane. A Heavy weapon uses Braced Shot; plan the two-action cost before moving. A flamer or other short-range weapon needs a covered approach.','주력 총기 하나와 사격 위치를 정하세요. 헤비 원거리 무기는 브레이스드 샷의 행동 2개 비용을 고려해야 합니다. 플레이머 등 단거리 무기는 엄폐된 접근로가 필요합니다.'):role==='runner'?P('Prioritise reaching objectives and surviving. Avoid turning an inexpensive objective model into an isolated expensive duellist.','목표 도달과 생존을 우선하세요. 저렴한 목표 담당에게 고가 무기를 몰아주어 고립된 결투 담당으로 만들지 마세요.'):P('Keep this model close enough to support another fighter. A basic gun and a clear job are easier to use than several expensive weapons without a plan.','다른 파이터를 지원할 수 있는 거리를 유지하세요. 계획 없이 비싼 무기를 여러 개 들기보다 기본 총기와 명확한 역할부터 익히는 편이 쉽습니다.')}</article>`;}).join('');
 const skills=show.map(({type:t,role})=>{const fixed=(R().fighterDefaults||[]).filter(r=>r.fighter_type_id===t.id&&r.skill_id).map(r=>(R().skills||[]).find(s=>s.id===r.skill_id)).filter(Boolean),chosen=startSkills(t,role),special=(t.fighter_subtypes||[]).includes('Specialist');return `<article class="gg-card"><h3>${ref('fighterTypes',t)}</h3>${fixed.length?`<p>${L('Fixed grants','자동·고정 지급')}: ${fixed.map(s=>ref('skills',s)).join(' · ')}</p>`:''}${t.free_skill?`<p>${L('Choose ONE starting Primary skill; recommended options','시작 프라이머리 1개 선택 · 추천 후보')}</p><ol class="gg-skill-options">${chosen.map(s=>`<li>${ref('skills',s)}${P(s.description_en||'',s.description||s.description_en||'')}</li>`).join('')||L('Review the model’s configured access.','모델의 스킬 접근 설정을 확인하세요.')}</ol>${P('The first option is the beginner default; the others are alternatives for a different role. Choose one and read its checks and conditions before committing.','첫 후보를 입문용 기본 선택으로 권장하며, 나머지는 역할에 따른 대안입니다. 하나만 선택하고 필요한 판정·조건을 먼저 확인하세요.')}`:P('No extra free Primary choice is assumed for this model. Use only its actual fixed grants and recruitment choices.','이 모델에 추가 무료 프라이머리 선택권이 있다고 가정하지 않습니다. 실제 고정 지급·모집 선택을 따르세요.')}${special?`<p>${L('Specialist: choose a specialisation. Ranged example: Gunner → Hip-shooting; Scout → Clamber for mobility, Tech → Munitioneer for support. Each is an alternative, not three free skills.','스페셜리스트: 전문화 1개를 고릅니다. 사격 예시: 거너 → 힙슈팅, 기동 역할은 스카우트 → 클램버, 지원 역할은 테크 → 뮤니셔니어를 비교하세요. 세 개를 모두 받는 것이 아닙니다.')}</p>`:''}${t.starting_power_choice?P('This model also has a required starting-power choice. Resolve its own power list in recruitment; do not substitute an ordinary skill.','이 모델은 시작 파워 선택도 필요합니다. 모집창에서 전용 파워 목록을 처리하며 일반 스킬로 대체하지 않습니다.'):''}<p>${L('Growth priority when a qualifying result permits it','허용되는 성장 결과에서의 희망 우선순위')}: ${role==='leader'?L('Survival / psychology → support skills → weapon proficiency','생존·심리 안정 → 지원 스킬 → 주력 무기 숙련'):role==='support'?L('BS → survival → reload and movement support','BS 향상 → 생존 → 장전·이동 지원'):L('Mission movement / weapon proficiency → survival → role skills','임무 이동·주력 무기 숙련 → 생존 → 역할 스킬')}</p></article>`;}).join('');
 const growth=P('XP is cumulative. Reaching a new XP band grants a roll in the Post-cycle Advancement step; recruitment Starting XP does not grant free rolls. Roll 2D6 and choose a permitted result no higher than the roll. These priorities are goals, not a freely purchased skill tree.','XP는 누적됩니다. 새 경험치 구간에 도달하면 포스트 사이클 성장 단계에서 판정하며 모집 시 시작 XP만으로 무료 성장 굴림을 받지 않습니다. 2D6 결과 이하에서 허용된 결과를 고릅니다. 아래 우선순위는 목표이며 자유 구매식 스킬 트리가 아닙니다.')+`<div class="gg-rules">${rule('n26-core-xp-bands','XP bands','경험치 구간')}${rule('n26-core-advancement-table','Actual advancement table','실제 성장 표')}${rule('n26-core-advancement-caps','Characteristic limits','능력치 한계')}</div>`+P('A result of 5 offers a chosen Primary or random Secondary skill; 7–8 offers a chosen Secondary; 9 offers WS or BS improvement. Roll 12 can open other sets but still respects Type/Subtype restrictions. Improving WS/BS/Save lowers their target number. XP is not spent; apply the listed rating increase.','결과 5는 프라이머리 선택 또는 세컨더리 무작위, 7–8은 세컨더리 선택, 9는 WS·BS 향상을 제공합니다. 12의 다른 세트 선택도 모델·서브타입 제한을 지켜야 합니다. WS·BS·세이브 향상은 목표 숫자가 낮아지는 방향입니다. XP를 소비하지 않으며 표의 레이팅 증가를 적용합니다.');
 const play=`<ol class="gg-steps"><li>${P('Before recruitment: agree on edition, budget, scenario and gang-specific composition rules. Choose the gang’s required path or affiliation before its leader.','모집 전: 판본·예산·시나리오·갱별 구성 규칙을 합의하세요. 필수 길·소속이 있는 갱은 리더보다 먼저 정합니다.')}</li><li>${P('Deploy: assign a firing base, an advance team and objective movers. Mark safe approaches; do not send the Leader alone into an exposed lane.','배치: 사격 거점·전진조·목표 이동조를 나눕니다. 엄폐된 접근로를 정하고 리더를 개방된 사선에 혼자 보내지 마세요.')}</li><li>${P('During the round: alternate Ready activations. Activate a cheap model to learn the opponent’s response, then commit valuable models with support. Check status and action cost before declaring a Double action.','라운드 중: 레디 모델을 번갈아 활성화합니다. 저렴한 모델로 상대 반응을 확인한 뒤 고가 모델을 지원과 함께 투입하세요. 더블 행동을 선언하기 전에 상태와 행동 비용을 확인합니다.')}</li><li>${P('Attack: declare targets, check range and terrain, then follow the weapon’s real profile. Read its traits instead of assuming a familiar name works as it did in another edition.','공격: 대상을 선언하고 거리·지형을 확인한 뒤 실제 무기 프로필을 따릅니다. 익숙한 이름이라고 다른 판본의 효과를 가정하지 말고 트레잇을 읽으세요.')}</li><li>${P('After battle: resolve survival and injuries before planning replacements. Record earned XP, check new bands, then budget for losses, income and the actual Trading Post visit.','전투 후: 생존·부상을 처리한 뒤 충원을 계획합니다. 실제 획득 XP와 새 구간을 확인하고 손실·수입·실제 거래소 방문 절차를 고려해 예산을 배분하세요.')}</li></ol><div class="gg-rules">${rule('n26-core-action-economy','Action economy','행동 비용')}${rule('n26-core-objectives','Objectives','목표 통제')}${rule('n26-core-bottle-check','Bottle checks','보틀 체크')}${rule('n26-core-post-cycle-sequence','Post-cycle','포스트 사이클')}</div>`;
 const fighters=g.fighters||[],active=fighters.filter(f=>!['Dead','Retired','Enslaved','Destroyed'].includes(f.status)),leaders=active.filter(f=>(f.subtypes||[]).includes('Leader')),noGear=active.filter(f=>!f.equipment?.length);const check=`<div class="gg-budget"><span>${L('Current models','현재 모델')} ${fighters.length}</span><span>${L('Recorded Leaders','기록된 리더')} ${leaders.length}</span><span>${L('No recorded equipment','장비 기록 없음')} ${noGear.length}</span><span>${L('Current credits','현재 크레딧')} ${E(g.credits??0)} cr</span></div>${P('This is a planning snapshot, not an automatic legality certificate. Check the roster validator, individual profiles, recovery/capture state and any campaign exceptions before play. No fields are changed by this guide.','계획을 돕는 현재 명단 요약이며 자동 적법 판정서가 아닙니다. 전투 전 명부 검사·개별 프로필·회복/포획 상태와 캠페인 예외를 확인하세요. 이 가이드는 어떤 기록도 변경하지 않습니다.')}<div class="gg-rules">${rule('n26-core-gang-composition','Composition rules','구성 규칙')}${ref('gangTypes',p.type)}</div><ul class="gg-checklist"><li>${L('Exactly one eligible Leader?','적격 리더가 정확히 1명인가?')}</li><li>${L('Champion / Brute / Hanger-on ratio and gang exceptions checked?','챔피언·브루트·행어온 비율과 갱 예외를 확인했는가?')}</li><li>${L('Recruitment lists, weapon slots and star-marked weapons checked?','모집 장비 목록·무기 슬롯·별표 무기를 확인했는가?')}</li><li>${L('Fixed grants, specialisations and one-time starting choices separated?','고정 지급·전문화·1회성 시작 선택을 구분했는가?')}</li><li>${L('Enough models to score, plus a replacement reserve?','목표를 수행할 인원과 충원용 예비금이 있는가?')}</li></ul>`;
 return `<div class="gg-guide">${overview}<div class="gg-tabs" role="tablist" aria-label="Guide sections" data-i18n-ko-aria-label="가이드 항목">${tabs.map(([id,en,ko])=>`<button type="button" role="tab" id="gg-tab-${id}" aria-controls="gg-panel-${id}" aria-selected="${id==='about'}" tabindex="${id==='about'?'0':'-1'}" data-guide-tab="${id}">${L(en,ko)}</button>`).join('')}</div>${section('about',reading(p.type))}${section('faction',factionContent(g))}${section('start',paths+roster(p)+`<h3>${L('First purchases','첫 구매 원칙')}</h3>`+P('Keep several affordable fighters rather than putting every upgrade on the Leader. Reserve credits are intentional; adjust the example to the mission, local terrain and campaign budget.','모든 업그레이드를 리더에게 몰아주기보다 부담 없는 파이터를 여러 명 유지하세요. 예비금은 의도적으로 남긴 것입니다. 임무·지형·캠페인 예산에 맞춰 조정하세요.'))}${section('gear',`<div class="gg-note">${L('Listed alternatives use this model’s verified recruitment access and price. They are alternatives, not a recommendation to buy every item.','표시된 대안은 해당 모델의 확인된 모집 접근·가격을 사용합니다. 대안 목록이며 전부 구매하라는 뜻이 아닙니다.')}</div><div class="gg-grid">${unitCards}</div>`+P('Armour is not a universal shortcut: Mesh armour in this N26 catalogue improves melee Saves by one; it is not a blanket ranged Save bonus. Heavy weapons and starred weapon slots also need their own checks.','아머를 만능 해법으로 생각하지 마세요. 이 N26 카탈로그의 메시 아머는 근접 세이브를 1 향상시키며 모든 사격에 일괄 보너스를 주는 효과가 아닙니다. 헤비 무기와 별표 무기 슬롯도 각각 확인해야 합니다.'))}${section('growth',growth+`<div class="gg-grid">${skills}</div><h3>${L('Campaign purchase order','캠페인 구매 우선순위')}</h3>`+P('After the first battle, replace essential missing roles before buying a luxury weapon. Next improve protection or a weapon only on the model that regularly uses it. Keep an objective team and a replacement reserve while adding a second specialist role.','첫 전투 후에는 고가 무기를 사기 전에 빠진 핵심 역할부터 충원하세요. 다음에는 실제로 자주 쓰는 모델의 보호 수단·주력 무기를 보강합니다. 목표 담당 인원과 충원 예비금을 유지하면서 두 번째 특화 역할을 추가하세요.'))}${section('play',play)}${section('check',check)}</div>`;
}
function open(g=gang()){if(!g)return false;context={g,path:'pious'};window.MMRuleReference.openContext('Beginner Gang Guide',content(g,context.path),{nameKo:'초보자 추천 갱 가이드',activator:document.activeElement});document.querySelector('.mmrr-dialog')?.classList.add('gg-dialog');return true;}
function tab(id){const host=document.querySelector('.gg-guide');if(!host)return;for(const b of host.querySelectorAll('[role=tab][data-guide-tab]')){const on=b.dataset.guideTab===id;b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1;}for(const p of host.querySelectorAll('[data-guide-panel]'))p.hidden=p.dataset.guidePanel!==id;}
window.addEventListener('click',e=>{const b=e.target.closest?.('[data-gang-guide],[data-gang-faction],[data-guide-tab],[data-guide-kind],[data-guide-path]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();if(b.hasAttribute('data-gang-guide'))return open();if(b.hasAttribute('data-gang-faction'))return openFaction();if(b.dataset.guideTab)return tab(b.dataset.guideTab);if(b.dataset.guidePath&&context){context.path=b.dataset.guidePath;window.MMRuleReference.openContext('Beginner Gang Guide',content(context.g,context.path),{nameKo:'초보자 추천 갱 가이드'});document.querySelector('.mmrr-dialog')?.classList.add('gg-dialog');tab('start');return;}if(b.dataset.guideKind)return window.MMRuleReference.open(b.dataset.guideKind,b.dataset.guideId,{edition:'n26',nested:true,activator:b});},true);
window.addEventListener('keydown',e=>{if(!e.target.matches?.('[role=tab][data-guide-tab]')||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const all=[...e.target.closest('.gg-tabs').querySelectorAll('button')],i=all.indexOf(e.target),next=e.key==='Home'?0:e.key==='End'?all.length-1:(i+(e.key==='ArrowRight'?1:-1)+all.length)%all.length;tab(all[next].dataset.guideTab);all[next].focus();});
const prior=gangTop;gangTop=function(g){const html=prior(g);return html.replace('<div class="entity-actions main-actions">',`<div class="entity-actions main-actions"><button class="btn small" type="button" data-gang-faction>${L('Faction Rules','팩션 룰')}</button><button class="btn small" type="button" data-gang-guide>${L('Beginner Guide','초보자 가이드')}</button>`);};window.MMGangGuide={open,openFaction,plan,equipment,primary,profiles,factionRules};
})();
